  function banner(){return !storageAvailable?`<div class="memory-banner" role="status">${icon('info')}이 브라우저에서는 저장할 수 없어 이번 방문 동안만 유지돼요. 새로고침하면 초기화돼요.</div>`:recoveryNotice?`<div class="memory-banner" role="status">저장된 정보를 읽지 못해 처음 상태로 복구했어요. 다시 설정해주세요.</div>`:'';}
  // 찜: 하트는 카드 버튼 밖(겹쳐 놓은 별도 버튼)이라 카드를 눌러도 찜이 바뀌지 않는다.
  const isFav=id=>M.favoritesOf(state).includes(id);
  const heartSvg='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 20.5s-8.5-5.2-8.5-11A4.8 4.8 0 0 1 12 6.7a4.8 4.8 0 0 1 8.5 2.8c0 5.8-8.5 11-8.5 11Z"/></svg>';
  function favButton(recipe,extra=''){const on=isFav(recipe.id);return `<button class="fav-button ${on?'on':''} ${extra}" data-action="favorite" data-id="${recipe.id}" aria-pressed="${on}" aria-label="${recipe.name} ${on?'즐겨찾기 해제':'즐겨찾기'}">${heartSvg}</button>`;}
  function cardWrap(recipe,horizontal,card){return `<div class="card-wrap ${horizontal?'horizontal':''}">${card}${favButton(recipe)}</div>`;}
  function recipeCard(recipe,horizontal=false){const s=recipe.status||M.recipeStatus(recipe,state);const missing=[...s.missingIngredients.map(id=>nameOf(id)),...s.missingCondiments.map(id=>nameOf(id,'condiments'))];return cardWrap(recipe,horizontal,`<button class="recipe-card ${horizontal?'horizontal':''}" data-action="recipe" data-id="${recipe.id}" aria-label="${recipe.name}, ${D.difficultyNames[recipe.difficulty]}, ${recipe.minutes}분${!s.hasTools?', 도구 필요':missing.length?', 부족: '+missing.join(', '):', 바로 만들 수 있음'} — 예시 상세 보기">${foodArt(recipe)}<div class="recipe-copy"><h3>${recipe.name}</h3>${recipe.mealType?`<span class="meal-type">${recipe.mealType}</span>`:''}<div class="recipe-meta"><span class="badge ${recipe.difficulty}">${D.difficultyNames[recipe.difficulty]}</span><span>${icon('clock')}${recipe.minutes}분</span><span>${icon('pan')}${names(recipe.tools,'tools')||'가열 없이'}</span></div>${!s.hasTools?`<span class="missing-badge">필요 도구: ${names(recipe.tools.filter(id=>!state.tools.includes(id)),'tools')}</span>`:''}${missing.length?`<span class="missing-badge">부족: ${missing.join(', ')}</span>`:''}</div>${horizontal?`<span class="card-arrow">${icon('chevron')}</span>`:''}</button>`);}
  function emptyBlock(title,description,action,label,emoji='🌱'){return `<div class="empty-state"><div class="empty-icon" aria-hidden="true">${emoji}</div><h3>${title}</h3><p>${description}</p>${action?`<button class="secondary-button" data-action="${action}">${label} ${icon('chevron')}</button>`:''}</div>`;}
  function mainEmpty(){if(!state.ingredients.length)return emptyBlock('냉장고가 아직 비어 있어요','지금 있는 재료 하나부터<br>차근차근 담아볼까요?','fridge','재료 담으러 가기','🥚');return '';}
  // 홈 = 게임 화면처럼 꽉 찬 블록 부엌. 추천 두 묶음은 아래 버튼으로 두고, 누르면 패널이 올라온다(기본 닫힘).
  function teaserOf(list){return list.length?`${list.slice(0,2).map(r=>r.name).join(' · ')}${list.length>2?` 외 ${list.length-2}개`:''}`:'아직 해당하는 요리가 없어요';}
  function drawer(id,title,list,body){const open=openSections[id];const anim=justOpened===id;if(anim)justOpened=null;return `<section class="home-drawer ${anim?'animate':''}" id="drawer-${id}" ${open?'':'hidden'} aria-label="${title}"><div class="drawer-head"><h2>${title}<span class="recipe-group-count">${list.length}개</span></h2><button class="drawer-close" data-action="toggle-section" data-id="${id}" aria-expanded="${open}" aria-controls="drawer-${id}">닫기 ▼</button></div><div class="drawer-body">${body}</div></section>`;}
  // 룰렛 뽑기: 후보(최대 8개)를 바퀴에 올려 돌리고, 포인터가 가리키는 요리로 멈춘다. 다시 돌리기는 한 번 열 때마다 3회.
  const rouletteIcon='<svg class="roulette-icon" viewBox="0 0 40 40" aria-hidden="true"><g stroke="#5b3a2b" stroke-width="2" stroke-linejoin="round"><path d="M20 20 20 5A15 15 0 0 1 33 12.5Z" fill="#f59a86"/><path d="M20 20 33 12.5A15 15 0 0 1 33 27.5Z" fill="#fff1c2"/><path d="M20 20 33 27.5A15 15 0 0 1 20 35Z" fill="#cfe7bd"/><path d="M20 20 20 35A15 15 0 0 1 7 27.5Z" fill="#cfe7f3"/><path d="M20 20 7 27.5A15 15 0 0 1 7 12.5Z" fill="#f6d2e6"/><path d="M20 20 7 12.5A15 15 0 0 1 20 5Z" fill="#ffd9a8"/><circle cx="20" cy="20" r="3.5" fill="#fffaf0"/><path d="M16 1.5h8L20 8Z" fill="#5b3a2b"/></g></svg>';
  const WHEEL_COLORS=['#ffd9cf','#fff1c2','#dcefd0','#d9ecf7','#f6dff0','#ffe5bf','#e6e1f7','#d6f0e9'];
  const roulette={segments:[],winner:null,spinsLeft:3,rotation:0,spinning:false};
  function shuffle(list){const a=[...list];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
  const bookIcon='<svg class="dock-icon" viewBox="0 0 40 40" aria-hidden="true"><g stroke="#5b3a2b" stroke-width="2" stroke-linejoin="round"><path d="M4 11v20c6-2 11-1 16 2 5-3 10-4 16-2V11c-6-2-11-1-16 2-5-3-10-4-16-2Z" fill="#c95a4a"/><path d="M6 9.5v19c5-1.6 9.5-.8 14 2V12c-4.5-2.8-9-3.6-14-2.5Z" fill="#fffaf0"/><path d="M34 9.5v19c-5-1.6-9.5-.8-14 2V12c4.5-2.8 9-3.6 14-2.5Z" fill="#fff1d6"/><path d="M9.5 15.5c2.6-.5 5-.1 7 1M9.5 20c2.6-.5 5-.1 7 1M23.5 16.5c2-1.1 4.4-1.5 7-1M23.5 21c2-1.1 4.4-1.5 7-1" fill="none" stroke-width="1.6"/><path d="M27 6v10l2.2-1.6L31.4 16V6Z" fill="#f59a86"/></g></svg>';
  function randomButton(rec){const pool=M.randomPool(rec);return `<button class="dock-action dock-roulette" data-action="random" ${pool.length?'':'disabled'} aria-label="요리 랜덤 돌리기, ${pool.length}개 요리 중에서">${rouletteIcon.replace('class="roulette-icon"','class="dock-icon roulette-icon"')}<span class="dock-action-text"><strong>요리 랜덤 돌리기</strong>${pool.length?`<span class="count-pill">${pool.length}개</span>`:'<small>후보 요리가 없어요</small>'}</span></button>`;}
